const { 装载前端, 设项目 } = require('./frontend-sandbox');
const ctx = 装载前端();
await 设项目(ctx, 'TK');
const 叫过 = [];
ctx.fetch = async (u) => {
  const url = decodeURIComponent(String(u)); 叫过.push(url);
  const J = (o) => ({ ok: true, json: async () => o });
  if (url === '/api/schedule') return J({ 粒: [
    { 粒ID:'g1', 题:'TK活儿', 项目:'TK', 状态:'计划', 批:'A', 序:1 },
    { 粒ID:'g2', 题:'TF活儿', 项目:'Ticketflow', 状态:'计划', 批:'B', 序:1 } ], 计数:{}, 名册:{} });
  if (url.startsWith('/api/schedule/队列')) {           // 桩子照后端那样真按参数筛
