    const 全 = [{ 批:'A', 项目:'TK', 粒:[{粒ID:'g1',题:'TK活儿'}] },
                { 批:'B', 项目:'Ticketflow', 粒:[{粒ID:'g2',题:'TF活儿'}] }];
    const 批们 = (p ? 全.filter((b) => b.项目 === p) : 全)
      .map((b) => ({ ...b, 完结:false, 折叠:false, 计数:{总:1,未完:1,完:0} }));
    return J({ 摘要:{ 文:`${批们.length} 批 · ${批们.length} 项未完` }, 批们 });
  }
  return J({});
};
const html = await ctx.viewRelay();
assert.ok(叫过.some((u) => u.startsWith('/api/schedule/队列') && u.includes('项目=TK')),
  '队列口必须带项目参数——不带就是第二把尺，实叫：' + JSON.stringify(叫过.filter((u)=>u.includes('队列'))));
assert.ok(!html.includes('TF活儿'), '别家项目的待办不许铺在 TK 页上（制作人 2026-08-21 点名的正是这个）');
assert.match(html, /待办 1 条在排/, '页头按 项目 算');
assert.match(html, /1 批 · 1 项未完/, '队列卡必须报同一个数——两个数就是两把尺');
```

