// artifacts.js — 打包产物留存（2026-08-22 体检）。
// 案源：换装只拷不清，dist 与部署目录只进不出——08-21 实测 dist 积到 134 exe / 9.1GB、
// 部署目录 72 exe / 4.8GB，占尽 D: 盘余量（当日剩 2.4%）。存量后来被手工清了，但脚本没改，
// 不加策略就会原样长回去。按 **mtime** 排，不按文件名——dist 里同时存在 0.17.1 与 0.17.10。
const fs = require('fs');
const path = require('path');
function 剪(dir, { 保留 = 6, 必保 = [] } = {}) {
  if (!fs.existsSync(dir)) return { 删: [], 留: [] };
  const 保 = new Set([].concat(必保).filter(Boolean).map(String));
  const 件 = fs.readdirSync(dir).filter((f) => /^监制台 .+\.exe$/.test(f))
    .map((f) => ({ f, 版: (f.match(/^监制台 (.+)\.exe$/) || [])[1], t: fs.statSync(path.join(dir, f)).mtimeMs }))
    .sort((a, b) => b.t - a.t);
  const 留 = []; const 删 = [];
  for (const x of 件) { if (留.length < 保留 || 保.has(x.版)) 留.push(x.f); else 删.push(x.f); }
  for (const f of 删) fs.rmSync(path.join(dir, f), { force: true });
  return { 删, 留 };
}
if (require.main === module) {
  const a = process.argv.slice(2);
  const 取 = (k) => { const i = a.indexOf(k); return i >= 0 ? a[i + 1] : null; };
  const r = 剪(取('--剪'), { 保留: Number(取('--保留') || 6), 必保: (取('--必保') || '').split(',').filter(Boolean) });
  console.log(`产物留存 ${取('--剪')}：留 ${r.留.length} 删 ${r.删.length}${r.删.length ? '（' + r.删.join('、') + '）' : ''}`);
}
module.exports = { 剪 };
