  // notify-diff.js — 桌面通知「哪几笔是新的」的唯一算法（2026-08-22 复核抽出）。
  // 抽出来的唯一理由：留在 main.js 里就只能用 assert.match(源码, /gateKey/) 这种文本判据，
  // 而实测把它换回「按计数上涨」，那三条正则一条都不红——判据是纸老虎。
  // 抽成纯函数后可以真喂两批债跑一遍：计数不变但 key 变了，必须报出新增的那笔。
  const 键 = (x) => String((x && x.gateKey) || (x && x.id) || '');
