// rootlock.js — 数据根单写者锁。锁的是 监制台/ 这个数据根，不是 Electron app：
// 08-20 那三对相隔 4.7s 的重复急件，根因是两个进程各跑各的 15 分钟拍，与外壳是不是 Electron 无关。
// 防死锁（08-20 断电案 + 换装.ps1 的 Stop-Process -Force）：pid 不存活、或 pid 存活但锁文件
// 超过 陈旧毫秒 没被续期，一律判陈旧可抢——宁可漏锁一次，不可让计划任务永久拒启。
const fs = require('fs'); const path = require('path');
const 锁文件 = (root) => path.join(root, '.studio.lock');
function 活着(pid) { try { process.kill(pid, 0); return true; } catch (e) { return e.code === 'EPERM'; } }
function 占(root, { 陈旧毫秒 = 120000, now = Date.now() } = {}) {
  const f = 锁文件(root);
  try {
    const o = JSON.parse(fs.readFileSync(f, 'utf8'));
    const 新鲜 = now - Number(new Date(o.续期 || o.起 || 0)) < 陈旧毫秒;
    if (o.pid !== process.pid && 活着(Number(o.pid)) && 新鲜) return { ok: false, 占用者: o };
  } catch { /* 无锁文件/坏锁文件都当可占 */ }
  fs.writeFileSync(f, JSON.stringify({ pid: process.pid, exe: process.execPath, 起: new Date(now).toISOString(), 续期: new Date(now).toISOString() }) + '\n', 'utf8');
  return { ok: true };
}
function 续期(root, { now = Date.now() } = {}) {
  const f = 锁文件(root);
  try { const o = JSON.parse(fs.readFileSync(f, 'utf8')); if (o.pid !== process.pid) return false;
    o.续期 = new Date(now).toISOString(); fs.writeFileSync(f, JSON.stringify(o) + '\n', 'utf8'); return true; } catch { return false; }
}
function 放(root) { try { const o = JSON.parse(fs.readFileSync(锁文件(root), 'utf8')); if (o.pid === process.pid) fs.unlinkSync(锁文件(root)); } catch { /* 已被清 */ } }
module.exports = { 占, 续期, 放, 锁文件 };
```
