      const 锁 = require('./lib/rootlock').占(ROOT);
      if (!锁.ok) {
        journal.append(ROOT, \`已有实例在跑（pid \${锁.占用者 && 锁.占用者.pid}），本进程只读挂起：不起执行器、不起巡检拍\`);
        console.error('[监制台] 数据根已被 pid ' + (锁.占用者 && 锁.占用者.pid) + ' 占用，本次不起执行器');
      } else {
        setInterval(() => require('./lib/rootlock').续期(ROOT), 30000).unref();
